import config from '@payload-config'
import { getPayload } from 'payload'
import Link from 'next/link'
import { notFound, permanentRedirect, redirect } from 'next/navigation'
import { headers as requestHeaders } from 'next/headers'

import { canDiscoverPublic, canRenderPublic, type PublicState } from '@/modules/public/contracts'
import type { Metadata } from 'next'
import {
  discoveryToMetadata,
  resolveDiscoveryDocument,
  resolveRedirect,
  serializeJsonLd,
  type RedirectRule,
} from '@/modules/public/discovery'
import { PublicLayout } from '@/modules/public/PublicLayout'
import { PublicForm } from '@/modules/audience/PublicForm'
import type { FormField } from '@/modules/audience/contracts'
import { BookReader, isReleasedChapter, relatedId } from '@/modules/media/books'
import { EditorialArticleView } from '@/modules/editorial/ArticleView'
import { loadPublishedArticleByPath } from '@/modules/editorial/persistence'
import { findIfRegistered, registeredOnly } from '@/modules/public/registered-collections'
import { resolveSiteSettings } from '@/modules/core/site-settings'
import { PresentationSurface } from '@/modules/presentation/Surface'
import type { Surface } from '@/modules/presentation/contracts'
import { CommentSection } from '@/modules/community/components/CommentSection'
import { getPublicSsrComments } from '@/modules/community/thread-lifecycle'
import { ProductDetail } from '@/modules/commerce/ProductView'
import { catalogSiteForHost } from '@/modules/commerce/site-scope'
import { hasEntitlement } from '@/modules/commerce/subscription-service'
import { currentMember, readMemberSession } from '@/modules/identity/member-identity'
import { canReadEvent } from '@/modules/events/public'
import { isSafeSemanticRequestPath } from '@/modules/public/semantic-url'
import { log } from '@/modules/core/logging'

type Args = {
  params: Promise<{ path: string[] }>
  searchParams?: Promise<Record<string, string | string[] | undefined>>
}
type PublicRecord = PublicState & Record<string, unknown>

const candidates = [
  'content',
  'books',
  'events',
  'timelines',
  'albums',
  'discussions',
  'products',
  'topics',
] as const

function label(record: PublicRecord): string {
  return String(record.title ?? record.name ?? record.displayName ?? 'Publication')
}

function kind(
  collection: (typeof candidates)[number],
): 'article' | 'event' | 'timeline' | 'album' | 'forum' | 'product' | 'topic' {
  if (collection === 'events') return 'event'
  if (collection === 'timelines') return 'timeline'
  if (collection === 'albums') return 'album'
  if (collection === 'discussions') return 'forum'
  if (collection === 'topics') return 'topic'
  return 'article'
}

function getSurfaceForCollection(collection: string, record: PublicRecord): Surface {
  if (collection === 'events') return 'event'
  if (collection === 'discussions') return 'forum'
  if (collection === 'products') return 'product'
  if (collection === 'topics') return 'archive'
  if (collection === 'books') return 'book'
  if (collection === 'content') {
    return record.contentType === 'page' ? 'page' : 'article'
  }
  return collection as Surface
}

export const dynamic = 'force-dynamic'

export async function generateMetadata({ params }: Args): Promise<Metadata> {
  const path = `/${(await params).path.join('/')}`
  if (!isSafeSemanticRequestPath(path)) return { robots: { index: false, follow: false } }
  try {
    const payload = await getPayload({ config })
    const siteId = await catalogSiteForHost(payload, (await requestHeaders()).get('host'))
    const discovery = await resolveDiscoveryDocument(payload, { path, siteId })
    return discoveryToMetadata(discovery)
  } catch {
    /* safe noindex fallback during recovery */
  }
  return { robots: { index: false, follow: false } }
}

export default async function CanonicalPublicPage({ params, searchParams }: Args) {
  const path = `/${(await params).path.join('/')}`
  if (!isSafeSemanticRequestPath(path)) notFound()
  const query = new URLSearchParams(
    Object.entries((await searchParams) ?? {}).flatMap(([key, value]) =>
      Array.isArray(value)
        ? value.map((entry) => [key, entry])
        : value === undefined
          ? []
          : [[key, value]],
    ),
  ).toString()
  const payload = await getPayload({ config })
  const siteId = await catalogSiteForHost(payload, (await requestHeaders()).get('host')).catch(
    () => null,
  )
  if (!siteId) notFound()
  const settings = await resolveSiteSettings(payload)

  const publications = await payload.find({
    collection: 'publications',
    where: {
      and: [
        { site: { equals: siteId } },
        { status: { equals: 'active' } },
        { visibility: { equals: 'public' } },
      ],
    },
    sort: '-createdAt',
    limit: 1,
    depth: 0,
    overrideAccess: true,
  } as never)
  const publication = publications.docs[0] as unknown as Record<string, unknown> | undefined
  if (!publication) notFound()

  const redirects = await payload
    .find({
      collection: 'public-redirects',
      where: { site: { equals: siteId } },
      limit: 1000,
      depth: 0,
      overrideAccess: true,
    } as never)
    .catch(() => ({ docs: [] }))
  const resolution = resolveRedirect(
    (redirects.docs as unknown as Array<Record<string, unknown>>).map((item) => ({
      id: String(item.id),
      siteId,
      fromPath: String(item.fromPath),
      toPath: String(item.toPath),
      match: item.match as RedirectRule['match'],
      statusCode: Number(item.statusCode) as RedirectRule['statusCode'],
      preserveQuery: item.preserveQuery !== false,
      enabled: item.enabled !== false,
    })),
    siteId,
    path,
    query ? `?${query}` : '',
  )
  if (resolution && 'target' in resolution) {
    // Best-effort telemetry must not make a redirect unavailable.
    await Promise.all(
      resolution.ruleIds.map((id) =>
        payload.update({
          collection: 'public-redirects',
          id,
          data: {
            hitCount:
              Number(
                (redirects.docs as Array<{ id: unknown; hitCount?: unknown }>).find(
                  (rule) => String(rule.id) === id,
                )?.hitCount ?? 0,
              ) + 1,
            lastHitAt: new Date().toISOString(),
          },
          overrideAccess: true,
        } as never),
      ),
    ).catch(() => undefined)

    // Add additional redirect metadata for analytics
    try {
      const reqHeaders = await (await import('next/headers')).headers()
      const userAgent = reqHeaders.get('user-agent') ?? 'unknown'
      const referer = reqHeaders.get('referer') ?? 'direct'

      // Log redirect event for analytics (in a real implementation, this would go to an analytics service)
      log('info', 'redirect.resolved', {
        from: path,
        to: resolution.target,
        statusCode: resolution.statusCode,
        userAgent,
        referer,
      })
    } catch {
      // Ignore analytics logging errors
    }

    if (resolution.statusCode === 301 || resolution.statusCode === 308)
      permanentRedirect(resolution.target)
    redirect(resolution.target)
  }
  if (resolution) notFound()

  const formResult = await findIfRegistered(payload, {
    collection: 'form-definitions',
    where: { and: [{ publicPath: { equals: path } }, { site: { equals: siteId } }] },
    limit: 1,
    depth: 1,
    overrideAccess: true,
  } as never)
  const form = formResult.docs[0] as unknown as {
    id: string
    name: string
    title?: string
    copy?: string
    visibility: string
    activeSchema?: {
      schema?: { fields?: FormField[] }
      consentText?: string
      state?: string
    }
  }
  if (form) {
    const schema = form.activeSchema
    if (form.visibility !== 'public' || schema?.state !== 'published' || !schema.schema?.fields)
      notFound()
    return (
      <main className="max-w-xl mx-auto px-6 py-20">
        <section className="surface-card p-8 space-y-6">
          <h1 className="text-3xl font-bold">{form.title || form.name}</h1>
          {form.copy ? <p className="text-stone-700">{form.copy}</p> : null}
          <PublicForm
            formId={form.id}
            fields={schema.schema.fields}
            consentText={schema.consentText}
          />
        </section>
      </main>
    )
  }

  const layoutResult = await payload.find({
    collection: 'page-layouts',
    where: { and: [{ path: { equals: path } }, { site: { equals: siteId } }] },
    limit: 1,
    depth: 0,
    overrideAccess: true,
  } as never)
  const layoutRecord = layoutResult.docs[0] as unknown as PublicRecord | undefined
  if (layoutRecord) {
    if (!canRenderPublic(layoutRecord)) notFound()
    const discovery = await resolveDiscoveryDocument(payload, { path })
    return (
      <PresentationSurface surface="custom-page" record={layoutRecord} themeId={settings.themeId}>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: serializeJsonLd(discovery.schema.jsonLd),
          }}
        />
        <PublicLayout record={layoutRecord} path={path} />
      </PresentationSurface>
    )
  }

  let editorialArticle: Awaited<ReturnType<typeof loadPublishedArticleByPath>> | undefined
  try {
    editorialArticle = await loadPublishedArticleByPath(payload, { siteId, path })
  } catch {
    // Continue to non-editorial canonical collections below.
  }
  if (editorialArticle) {
    const required = editorialArticle.requiredEntitlement as {
      resource?: string
      capability?: string
      scope?: string
    } | null
    if (required?.resource && required.capability) {
      const memberId = await currentMember(
        payload as never,
        readMemberSession(await requestHeaders()),
      )
      if (
        !memberId ||
        !(await hasEntitlement(payload as never, {
          subjectId: memberId,
          siteId,
          resource: required.resource,
          capability: required.capability,
          ...(required.scope ? { scope: required.scope } : {}),
        }))
      )
        notFound()
    }
    const discovery = await resolveDiscoveryDocument(payload, { path })
    return (
      <>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: serializeJsonLd(discovery.schema.jsonLd),
          }}
        />
        <EditorialArticleView themeId={settings.themeId} article={editorialArticle} />
      </>
    )
  }

  const bookResult = await findIfRegistered(payload, {
    collection: 'books',
    where: { and: [{ site: { equals: siteId } }, { canonicalPath: { equals: path } }] },
    limit: 1,
    depth: 0,
    overrideAccess: true,
  } as never)
  const book = bookResult.docs[0] as unknown as PublicRecord | undefined
  if (book && canRenderPublic(book)) {
    const chapters = (
      await payload.find({
        collection: 'book-chapters',
        where: { book: { equals: String(book.id) } },
        limit: 500,
        depth: 0,
        overrideAccess: true,
      } as never)
    ).docs as unknown as PublicRecord[]
    return (
      <PresentationSurface surface="book" record={book} themeId={settings.themeId}>
        <BookReader book={book} chapters={chapters} />
      </PresentationSurface>
    )
  }

  const topicResult = await findIfRegistered(payload, {
    collection: 'topics',
    where: { and: [{ canonicalPath: { equals: path } }, { site: { equals: siteId } }] },
    limit: 1,
    depth: 0,
    overrideAccess: true,
  } as never)
  const topic = topicResult.docs[0] as unknown as PublicRecord | undefined
  if (topic) {
    const articles = await payload.find({
      collection: 'content',
      where: {
        and: [
          { site: { equals: siteId } },
          { topics: { contains: String(topic.id) } },
          { status: { in: ['published', 'updated'] } },
          { visibility: { equals: 'public' } },
          { moderationState: { equals: 'clear' } },
          { removeFromDiscovery: { not_equals: true } },
        ],
      } as never,
      sort: '-publishedAt',
      limit: 50,
      depth: 0,
      overrideAccess: true,
    } as never)
    const publicArticles = (articles.docs as unknown as PublicRecord[]).filter((article) =>
      canDiscoverPublic(article),
    )
    if (!publicArticles.length) notFound()
    const discovery = await resolveDiscoveryDocument(payload, {
      collection: 'topics',
      record: { ...topic, status: 'published', visibility: 'public' },
      path,
      siteId,
    })
    return (
      <PresentationSurface surface="archive" record={topic} themeId={settings.themeId}>
        <main className="mx-auto max-w-4xl space-y-8 px-6 py-12">
          <link rel="canonical" href={discovery.canonicalUrl} />
          <script
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: serializeJsonLd(discovery.schema.jsonLd) }}
          />
          <header className="space-y-3">
            <p className="text-sm text-stone-500">Topic</p>
            <h1 className="text-4xl font-bold">{String(topic.name)}</h1>
            {typeof topic.description === 'string' ? <p>{topic.description}</p> : null}
          </header>
          <ul className="space-y-5">
            {publicArticles.map((article) => (
              <li key={String(article.id)} className="surface-card p-5">
                <h2 className="text-xl font-semibold">
                  <Link href={String(article.canonicalPath)}>{label(article)}</Link>
                </h2>
                {typeof article.summary === 'string' ? <p>{article.summary}</p> : null}
              </li>
            ))}
          </ul>
        </main>
      </PresentationSurface>
    )
  }
  const chapterResult = await findIfRegistered(payload, {
    collection: 'book-chapters',
    where: { canonicalPath: { equals: path } },
    limit: 1,
    depth: 0,
    overrideAccess: true,
  } as never)
  const chapter = chapterResult.docs[0] as unknown as PublicRecord | undefined
  if (chapter && isReleasedChapter(chapter)) {
    const chapterBook = (await payload.findByID({
      collection: 'books',
      id: relatedId(chapter.book),
      depth: 0,
      overrideAccess: true,
    } as never)) as unknown as PublicRecord
    if (!chapterBook || relatedId(chapterBook.site) !== siteId || !canRenderPublic(chapterBook))
      notFound()
    const chapters = (
      await payload.find({
        collection: 'book-chapters',
        where: { book: { equals: String(chapterBook.id) } },
        limit: 500,
        depth: 0,
        overrideAccess: true,
      } as never)
    ).docs as unknown as PublicRecord[]
    const articleResult = relatedId(chapter.content)
      ? await payload.find({
          collection: 'article-family-content',
          where: { content: { equals: relatedId(chapter.content) } },
          limit: 1,
          depth: 0,
          overrideAccess: true,
        } as never)
      : { docs: [] }
    return (
      <PresentationSurface surface="book" record={chapterBook} themeId={settings.themeId}>
        <BookReader
          book={chapterBook}
          chapter={chapter}
          chapters={chapters}
          article={(articleResult.docs[0] ?? null) as unknown as PublicRecord | null}
        />
      </PresentationSurface>
    )
  }

  for (const collection of registeredOnly(payload, candidates)) {
    const result = await payload.find({
      collection,
      where: { and: [{ canonicalPath: { equals: path } }, { site: { equals: siteId } }] },
      limit: 1,
      depth: 0,
      overrideAccess: true,
    } as never)
    const record = result.docs[0] as unknown as PublicRecord | undefined
    if (!record) continue
    if (collection === 'products' && record.state !== 'published') notFound()
    if (!canRenderPublic(record)) notFound()
    if (collection === 'events' && !(await canReadEvent(payload, record, siteId))) notFound()

    const name = label(record)
    let articleBody: string | null = null
    if (collection === 'content') {
      const articleResult = await payload.find({
        collection: 'article-family-content',
        where: { content: { equals: String(record.id) } },
        limit: 1,
        depth: 0,
        overrideAccess: true,
      } as never)
      const projection = (
        articleResult.docs[0] as unknown as { plainTextProjection?: string } | undefined
      )?.plainTextProjection
      if (typeof projection === 'string' && projection) {
        articleBody = projection
      }
    }
    const discovery = await resolveDiscoveryDocument(payload, {
      path,
      record: record as Record<string, unknown>,
      collection,
    })
    if (collection === 'products') {
      return (
        <PresentationSurface surface="product" record={record} themeId={settings.themeId}>
          <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-12 md:py-16 space-y-8">
            <link rel="canonical" href={discovery.canonicalUrl} />
            <script
              type="application/ld+json"
              dangerouslySetInnerHTML={{ __html: serializeJsonLd(discovery.schema.jsonLd) }}
            />
            <ProductDetail product={record} />
          </main>
        </PresentationSurface>
      )
    }
    const targetSurface = getSurfaceForCollection(collection, record)
    return (
      <PresentationSurface surface={targetSurface} record={record} themeId={settings.themeId}>
        <main className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 md:py-16 space-y-8">
          <link rel="canonical" href={discovery.canonicalUrl} />
          <script
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: serializeJsonLd(discovery.schema.jsonLd) }}
          />
          <nav
            aria-label="Breadcrumb"
            className="flex items-center gap-2 text-xs font-semibold text-stone-500"
          >
            <Link href="/" className="hover:text-red-600 transition-colors">
              Home
            </Link>
            <span>/</span>
            <span className="badge badge-neutral">{kind(collection)}</span>
            <span>/</span>
            <span aria-current="page" className="text-stone-900 dark:text-stone-100">
              {name}
            </span>
          </nav>
          <article className="surface-card p-8 sm:p-10 space-y-6">
            <h1 className="text-3xl sm:text-5xl font-black tracking-tight text-stone-950 dark:text-stone-50 font-display">
              {name}
            </h1>
            {typeof record.summary === 'string' ? (
              <p className="text-lg sm:text-xl text-stone-600 dark:text-stone-300 font-display italic leading-relaxed">
                {record.summary}
              </p>
            ) : null}
            {articleBody ? (
              <div className="prose dark:prose-invert max-w-none text-base sm:text-lg leading-relaxed text-stone-800 dark:text-stone-200 whitespace-pre-line">
                {articleBody}
              </div>
            ) : typeof record.description === 'string' ? (
              <div className="prose dark:prose-invert max-w-none text-base sm:text-lg leading-relaxed text-stone-800 dark:text-stone-200">
                {record.description}
              </div>
            ) : null}
            {collection === 'events' && typeof record.startsAt === 'string' ? (
              <section aria-label="Event details" className="border-t pt-5 space-y-2">
                <h2>Event details</h2>
                <p>
                  <time dateTime={record.startsAt}>
                    Starts{' '}
                    {new Intl.DateTimeFormat(undefined, {
                      dateStyle: 'full',
                      timeStyle: record.allDay ? undefined : 'short',
                      timeZone: String(record.timeZone ?? 'UTC'),
                    }).format(new Date(record.startsAt))}
                  </time>{' '}
                  · {String(record.timeZone ?? 'UTC')}
                </p>
                {typeof record.endsAt === 'string' ? (
                  <p>
                    <time dateTime={record.endsAt}>
                      Ends{' '}
                      {new Intl.DateTimeFormat(undefined, {
                        dateStyle: 'full',
                        timeStyle: record.allDay ? undefined : 'short',
                        timeZone: String(record.timeZone ?? 'UTC'),
                      }).format(new Date(record.endsAt))}
                    </time>
                  </p>
                ) : null}
                {typeof record.venueName === 'string' ? (
                  <p>
                    {record.venueName}
                    {typeof record.venueAddress === 'string' ? ` — ${record.venueAddress}` : ''}
                  </p>
                ) : null}
                {typeof record.onlineUrl === 'string' ? (
                  <p>
                    <a href={record.onlineUrl}>Join online</a>
                  </p>
                ) : null}
                {typeof record.organizerName === 'string' ? (
                  <p>Organizer: {record.organizerName}</p>
                ) : null}
                {typeof record.registrationUrl === 'string' ? (
                  <p>
                    <a href={record.registrationUrl}>Register</a>
                  </p>
                ) : null}
                <p>
                  <a href={`/events/${record.slug}/ics`}>Add to calendar (ICS)</a>
                </p>
              </section>
            ) : null}
          </article>
          {collection === 'content' || collection === 'discussions' ? (
            <CommentSection
              attachedToId={String(record.id)}
              attachedToCollection={collection === 'content' ? 'content' : 'content'}
              canonicalPath={path}
              title={name}
              siteId={
                typeof record.site === 'string'
                  ? record.site
                  : String((record.site as { id?: string })?.id ?? 'default')
              }
              initialComments={await getPublicSsrComments(payload, {
                canonicalContentId: String(record.id),
                siteId:
                  typeof record.site === 'string'
                    ? record.site
                    : String((record.site as { id?: string })?.id ?? ''),
                contentStatus: String(record.status ?? record._status ?? 'published'),
                isIndexable: Boolean(discovery.indexability.indexable),
              })}
            />
          ) : null}
        </main>
      </PresentationSurface>
    )
  }
  notFound()
}
